const raw = $input.first().json.body ? ($input.first().json.id ? $input.first().json : $input.first().json.body) : $input.first().json;
if (!raw || !raw.id || !raw.from || !raw.from.email || !raw.received_at) {
  throw new Error('Invalid inbound email contract');
}
const bodyLower = String(raw.body || '').toLowerCase();
const isSensitiveMedical = /(eczema|psoriasis|acne|dermatitis|skin condition|cure|pregnan|allerg|reaction|rash|dermatologist|doctor)/.test(bodyLower);
const explicitOrderMatch = `${raw.subject || ''} ${raw.body || ''}`.toUpperCase().match(/\bKC-\d{4}\b/);
return [{
  json: {
    email_id: String(raw.id).trim(),
    received_at: raw.received_at,
    from_name: String(raw.from.name || 'there').trim(),
    from_email: String(raw.from.email).trim().toLowerCase(),
    subject: String(raw.subject || '').trim(),
    body: String(raw.body || '').trim(),
    attachments: Array.isArray(raw.attachments) ? raw.attachments : [],
    regex_order_id: explicitOrderMatch ? explicitOrderMatch[0] : null,
    is_sensitive_medical: isSensitiveMedical
  }
}];

