const email = $('Validate Payload & Privacy Screen').first().json;
const llmOut = $input.first().json.output || null;
const validIntents = new Set(['order_status', 'product_query', 'return_refund', 'complaint', 'other']);
let parsed = (llmOut && validIntents.has(llmOut.intent)) ? llmOut : {
  intent: 'other',
  secondary_intent: null,
  order_id: email.regex_order_id,
  sentiment: 'neutral',
  language: /[\u0900-\u097f]/.test(email.body) ? 'hi' : 'en',
  confidence: 0.45,
  summary: (email.subject || email.body).slice(0, 200),
  fallback_used: true
};
// Never allow hallucinated order IDs absent from the email text
const resolvedOrderId = email.regex_order_id;
const threshold = 0.75;
const lowConfidence = Number(parsed.confidence) < threshold || Boolean(parsed.fallback_used);
return [{
  json: {
    ...email,
    classification: { ...parsed, order_id: resolvedOrderId },
    low_confidence: lowConfidence
  }
}];

// Deterministic order ownership & date arithmetic (Scenario date: 2026-11-20; uses email.received_at)
const ctx = $('Schema Fallback & Confidence Gate (0.75)').first().json;
const orders = $input.first().json.orders || [];
const intent = ctx.classification.intent;
let order = null;
let lookupStatus = 'not_requested';
if (['order_status', 'return_refund', 'complaint'].includes(intent) && !ctx.low_confidence) {
  if (ctx.classification.order_id) {
    order = orders.find(o => o.order_id.toUpperCase() === ctx.classification.order_id.toUpperCase()) || null;
  } else {
    const matches = orders.filter(o => o.customer_email.toLowerCase() === ctx.from_email);
    order = matches.length === 1 ? matches[0] : null;
  }
  if (!order) {
    lookupStatus = 'not_found_or_ambiguous';
  } else if (order.customer_email.toLowerCase() !== ctx.from_email) {
    order = null;
    lookupStatus = 'sender_mismatch';
  } else {
    lookupStatus = 'verified';
  }
}
let daysSinceDelivery = null;
if (order && order.delivered_date) {
  const recDate = new Date(ctx.received_at.slice(0, 10) + 'T00:00:00Z');
  const delDate = new Date(order.delivered_date + 'T00:00:00Z');
  daysSinceDelivery = Math.floor((recDate - delDate) / 86400000);
}
return [{
  json: {
    ...ctx,
    order_lookup_status: lookupStatus,
    verified_order: order,
    days_since_delivery: daysSinceDelivery
  }
}];

// Python/JS policy eligibility evaluation for return_refund & complaint before ticket upsert
const item = $input.first().json;
const body = item.body.toLowerCase();
const order = item.verified_order;
const age = item.days_since_delivery;
const priority = (item.classification.intent === 'complaint' || item.classification.sentiment === 'angry') ? 'High' : 'Medium';
let policyDecision = 'verification_required';
if (order) {
  if (item.classification.intent === 'return_refund') {
    const opened = /(used them|using the|used |didn't suit|did not suit|no difference|no results)/.test(body);
    const sealed = /(unopened|sealed|seal intact)/.test(body);
    if (order.status === 'delivered' && age !== null && age >= 0 && age <= 7 && sealed && !opened) {
      policyDecision = 'eligible_for_review';
    } else if (opened) {
      policyDecision = 'outside_policy_opened_item';
    } else if (age !== null && age > 7) {
      policyDecision = 'outside_policy_window';
    } else {
      policyDecision = 'manual_policy_review';
    }
  } else {
    policyDecision = (age !== null && age >= 0 && age <= 1) ? 'within_48h_evidence_review' : 'outside_48h_manual_exception';
  }
}
return [{ json: { ...item, ticket_priority: priority, policy_decision: policyDecision } }];

