let match = wantedId.startsWith('KC-') ? orders.find(o => o.order_id === wantedId) : orders.find(o => o.customer_email.toLowerCase() === sender);
if (!match) return JSON.stringify({ status: 'not_found_or_ambiguous' });
if (match.customer_email.toLowerCase() !== sender) return JSON.stringify({ status: 'sender_mismatch', message: 'Order belongs to another customer; do not disclose.' });
const { shipping_address, customer_email, ...safeOrder } = match;
return JSON.stringify({ status: 'verified', ...safeOrder });

// Assemble final Audit Log row (enforces hard safety checks & needs_human flag)
const data = $input.first().json;
const needsHuman = Boolean(
  data.low_confidence ||
  data.is_sensitive_medical ||
  ['return_refund', 'complaint'].includes(data.classification?.intent) ||
  ['sender_mismatch', 'not_found_or_ambiguous'].includes(data.order_lookup_status)
);
return [{
  json: {
    email_id: data.email_id,
    received_at: data.received_at,
    from_email: data.from_email,
    intent: data.classification?.intent || 'other',
    secondary_intent: data.classification?.secondary_intent || '',
    order_id: data.verified_order?.order_id || data.classification?.order_id || '',
    language: data.classification?.language || 'en',
    sentiment: data.classification?.sentiment || 'neutral',
    confidence: data.classification?.confidence ?? 0,
    order_found: Boolean(data.verified_order),
    action_taken: data.classification?.intent === 'other' ? 'log_only' : (data.ticket_id ? 'ticket_created' : (needsHuman ? 'needs_human' : 'draft_reply')),
    needs_human: needsHuman,
    ticket_id: data.ticket_id || '',
    reply_draft: data.classification?.intent === 'other' ? '' : (data.output || ''),
    prompt_version: 'v2',
    processed_at: new Date().toISOString(),
    error: data.error || '',
    notes: data.policy_decision || data.order_lookup_status || ''
  }
}];
